const config = {
  "previewFeatures": [],
  "clientVersion": "7.10.1",
  "engineVersion": "d1b3f377ca835d73fd50954a5e22128b9ebdd6b8",
  "activeProvider": "postgresql",
  "inlineSchema": "// Prisma Schema for KARIBU Order Management Core\n// Derived directly from the KARIBU GraphQL API schema specifications.\n// Supports offline testing, migrations, and realistic mock data generation.\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\n// ----------------------------------------------------------------------------\n// 1. Reference & Lookup Enums / Status Tables\n// ----------------------------------------------------------------------------\n\nmodel Country {\n  id          Int       @id\n  name        String\n  alpha2      String    @unique\n  alpha3      String    @unique\n  callingCode String?\n  cluster     Int?\n  companies   Company[]\n  banks       Bank[]\n  vehicles    Vehicle[]\n  drivers     Driver[]\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n}\n\nmodel Company {\n  id                     Int                 @id\n  code                   String              @unique\n  name                   String\n  countryId              Int\n  country                Country             @relation(fields: [countryId], references: [id])\n  email                  String?\n  telephoneNumber        String?\n  customerTranscription  Boolean             @default(true)\n  defaultCurrencyCode    String              @default(\"GHS\")\n  defaultCurrencySymbol  String              @default(\"GH₵\")\n  allowDepotSelection    Boolean             @default(true)\n  allowOrderCancellation Boolean             @default(true)\n  allowOrderAmendment    Boolean             @default(false)\n  users                  User[]\n  locations              Location[]\n  customers              Customer[]\n  products               Product[]\n  destinations           Destination[]\n  paymentModes           PaymentMode[]\n  salesVouchers          SalesVoucher[]\n  salesVoucherOrders     SalesVoucherOrder[]\n  basketOrders           BasketOrder[]\n  createdAt              DateTime            @default(now())\n  updatedAt              DateTime            @updatedAt\n}\n\nmodel Location {\n  id                                    Int                 @id\n  code                                  String\n  name                                  String\n  companyId                             Int\n  company                               Company             @relation(fields: [companyId], references: [id])\n  type                                  String?             @default(\"PLANT\") // \"PLANT\" or \"DEPOT\"\n  allowDeliveryTypeSelection            Boolean             @default(true)\n  allowDeliveryTypeSelectionForProduct  Boolean             @default(false)\n  defaultDeliveryType                   String?             @default(\"EXW\") // \"EXW\" or \"DELIVERED\"\n  useLocalPoNumber                      Boolean             @default(false)\n  useFileUpload                         Boolean             @default(true)\n  requireFileUpload                     Boolean             @default(false)\n  useDescription                        Boolean             @default(true)\n  useComments                           Boolean             @default(true)\n  useDeliveryContact                    Boolean             @default(true)\n  useConfirmQuotation                   Boolean             @default(true)\n  useDeliveredOrderManagement           Boolean             @default(true)\n  requireDestinationSelectionForExworks Boolean             @default(false)\n  users                                 User[]\n  sourceVouchers                        SalesVoucher[]      @relation(\"SourceLocation\")\n  salesVoucherItems                     SalesVoucherItem[]  @relation(\"ItemSourceLocation\")\n  salesVoucherOrders                    SalesVoucherOrder[]\n  createdAt                             DateTime            @default(now())\n  updatedAt                             DateTime            @updatedAt\n}\n\nmodel Destination {\n  id                 Int                 @id\n  code               String\n  name               String\n  region             String?\n  country            String?\n  companyId          Int\n  company            Company             @relation(fields: [companyId], references: [id])\n  minDeliveryDays    Float?              @default(2.0)\n  distance           Float?\n  salesVouchers      SalesVoucher[]\n  salesVoucherItems  SalesVoucherItem[]\n  salesVoucherOrders SalesVoucherOrder[]\n  createdAt          DateTime            @default(now())\n  updatedAt          DateTime            @updatedAt\n}\n\n// ----------------------------------------------------------------------------\n// 2. Status & Code Dictionaries (mirrors GraphQL dictionary IDs)\n// ----------------------------------------------------------------------------\n\nmodel SalesVoucherStatus {\n  id             Int            @id // 0: WaitingForQuotation, 1: Quotation, 8: PaymentSubmitted, 9: SOGenerated, 10: QuotationGenerated, 12: Pending...\n  description    String\n  translationKey String?\n  salesVouchers  SalesVoucher[]\n}\n\nmodel SalesVoucherOrderStatus {\n  id                 Int                 @id // 10: Unconfirmed, 20: Confirmed, 30: Cancelled, 40: Dispatched, 50: Delivered\n  description        String\n  salesVoucherOrders SalesVoucherOrder[]\n}\n\nmodel BasketOrderStatus {\n  id           Int           @id // 1: Open, 2: InProgress, 3: Completed, 4: Expired\n  description  String\n  basketOrders BasketOrder[]\n}\n\nmodel PaymentStatus {\n  id             Int       @id // 1: Pending, 2: Approved, 3: Rejected, 4: Cancelled, 5: Closed, 6: TranscriptionRequired\n  description    String\n  translationKey String?\n  payments       Payment[]\n}\n\nmodel DocumentType {\n  id                    Int                    @id // 1: EPayment, 2: CashDepositSlip, 3: ChequeDepositSlip, 4: Cheque, 5: HaulageClaim, 6: CreditOrder, 7: BankTransferNote, 8: EndorsedDraft, 9: AvailableBalance\n  description           String\n  translationKey        String?\n  paymentModes          PaymentMode[]\n  paymentTranscriptions PaymentTranscription[]\n}\n\n// ----------------------------------------------------------------------------\n// 3. Banking & Payment Configurations\n// ----------------------------------------------------------------------------\n\nmodel Bank {\n  id                    Int                    @id\n  name                  String\n  code                  String\n  countryId             Int\n  country               Country                @relation(fields: [countryId], references: [id])\n  isActive              Boolean                @default(true)\n  bankBranches          BankBranch[]\n  paymentTranscriptions PaymentTranscription[]\n  createdAt             DateTime               @default(now())\n  updatedAt             DateTime               @updatedAt\n}\n\nmodel BankBranch {\n  id                    Int                    @id\n  name                  String\n  code                  String?\n  bankId                Int\n  bank                  Bank                   @relation(fields: [bankId], references: [id])\n  isActive              Boolean                @default(true)\n  paymentTranscriptions PaymentTranscription[]\n  createdAt             DateTime               @default(now())\n  updatedAt             DateTime               @updatedAt\n}\n\nmodel PaymentMode {\n  id                  Int          @id\n  name                String\n  documentTypeId      Int\n  documentType        DocumentType @relation(fields: [documentTypeId], references: [id])\n  companyId           Int\n  company             Company      @relation(fields: [companyId], references: [id])\n  paymentModeTypeId   Int          @default(2) // 1: E-Payment, 2: Manual/Other\n  paymentModeStatusId Int          @default(1) // 1: Active\n  payments            Payment[]\n  createdAt           DateTime     @default(now())\n  updatedAt           DateTime     @updatedAt\n}\n\n// ----------------------------------------------------------------------------\n// 4. Master Entities: Products, Customers, Users, Vehicles & Drivers\n// ----------------------------------------------------------------------------\n\nmodel Product {\n  id                 Int                 @id\n  itemCode           String\n  title              String\n  productGroup       String?             @default(\"Cement Bags\")\n  standardUnit       String?             @default(\"bags\")\n  weighPiece         Float?              @default(50.0) // 50kg per bag\n  unitPrice          Float?              @default(90.0) // estimated unit price in local currency\n  description        String?\n  isPublished        Boolean             @default(true)\n  companyId          Int\n  company            Company             @relation(fields: [companyId], references: [id])\n  salesVoucherItems  SalesVoucherItem[]\n  salesVoucherOrders SalesVoucherOrder[]\n  createdAt          DateTime            @default(now())\n  updatedAt          DateTime            @updatedAt\n}\n\nmodel Customer {\n  id                      Int                 @id\n  customerCode            String              @unique\n  customerName            String\n  email                   String?\n  phoneNumber             String?\n  companyId               Int\n  company                 Company             @relation(fields: [companyId], references: [id])\n  customerAccountBalance  Float               @default(0.0)\n  customerAvailableCredit Float               @default(0.0)\n  customerCrLimit         Float               @default(0.0)\n  customerOpenOrders      Float               @default(0.0)\n  customerStatus          Int?                @default(1)\n  customerStatusDesc      String?             @default(\"Active\")\n  customerCurrency        String?             @default(\"GHS\")\n  active                  Boolean             @default(true)\n  users                   User[]\n  salesVouchers           SalesVoucher[]\n  salesVoucherOrders      SalesVoucherOrder[]\n  basketOrders            BasketOrder[]\n  payments                Payment[]\n  createdAt               DateTime            @default(now())\n  updatedAt               DateTime            @updatedAt\n}\n\nmodel User {\n  id              String         @id @default(uuid())\n  userName        String         @unique\n  fullName        String?\n  email           String         @unique\n  phoneNumber     String?\n  isActive        Boolean        @default(true)\n  companyId       Int?\n  company         Company?       @relation(fields: [companyId], references: [id])\n  customerId      Int?\n  customer        Customer?      @relation(fields: [customerId], references: [id])\n  locationId      Int?\n  location        Location?      @relation(fields: [locationId], references: [id])\n  role            String?        @default(\"CUSTOMER\") // \"CUSTOMER\", \"SALES_OFFICER\", \"ADMIN\"\n  createdVouchers SalesVoucher[]\n  createdBaskets  BasketOrder[]\n  createdAt       DateTime       @default(now())\n  updatedAt       DateTime       @updatedAt\n}\n\nmodel Vehicle {\n  id                Int                @id @default(autoincrement())\n  vehicleNo         String             @unique\n  transporterCode   String?\n  countryId         Int\n  country           Country            @relation(fields: [countryId], references: [id])\n  capacity          Float?             @default(30.0) // tons\n  isActive          Boolean            @default(true)\n  salesVoucherItems SalesVoucherItem[]\n  createdAt         DateTime           @default(now())\n  updatedAt         DateTime           @updatedAt\n}\n\nmodel Driver {\n  id                Int                @id @default(autoincrement())\n  firstName         String\n  lastName          String\n  licenseNo         String             @unique\n  phoneNo           String?\n  transporterCode   String?\n  countryId         Int\n  country           Country            @relation(fields: [countryId], references: [id])\n  isActive          Boolean            @default(true)\n  salesVoucherItems SalesVoucherItem[]\n  createdAt         DateTime           @default(now())\n  updatedAt         DateTime           @updatedAt\n}\n\n// ----------------------------------------------------------------------------\n// 5. Order Management: Basket, Sales Voucher, Items & Sales Orders\n// ----------------------------------------------------------------------------\n\nmodel BasketOrder {\n  id                  Int                @id @default(autoincrement())\n  basketOrderNumber   String             @unique\n  totalQuantity       Float\n  quantityUsed        Float              @default(0.0)\n  quantityLeft        Float\n  salesVoucherCount   Int                @default(0)\n  customerId          Int\n  customer            Customer           @relation(fields: [customerId], references: [id])\n  companyId           Int\n  company             Company            @relation(fields: [companyId], references: [id])\n  createdById         String?\n  createdBy           User?              @relation(fields: [createdById], references: [id])\n  basketOrderStatusId Int                @default(1)\n  basketOrderStatus   BasketOrderStatus? @relation(fields: [basketOrderStatusId], references: [id])\n  salesVouchers       SalesVoucher[]\n  createdAt           DateTime           @default(now())\n  updatedAt           DateTime           @updatedAt\n}\n\nmodel SalesVoucher {\n  id                    Int                 @id @default(autoincrement())\n  voucherNumber         String              @unique\n  customerReference     String?\n  customOrderNumber     String?\n  orderQuote            Float? // backend-calculated quotation price\n  customerId            Int\n  customer              Customer            @relation(fields: [customerId], references: [id])\n  companyId             Int\n  company               Company             @relation(fields: [companyId], references: [id])\n  createdById           String?\n  createdBy             User?               @relation(fields: [createdById], references: [id])\n  sourceLocationId      Int\n  sourceLocation        Location            @relation(\"SourceLocation\", fields: [sourceLocationId], references: [id])\n  destinationId         Int?\n  destination           Destination?        @relation(fields: [destinationId], references: [id])\n  basketId              Int?\n  basket                BasketOrder?        @relation(fields: [basketId], references: [id])\n  salesVoucherStatusId  Int                 @default(12) // 12 = Pending, 1 = Quotation, 8 = PaymentSubmitted, 9 = SOGenerated\n  salesVoucherStatus    SalesVoucherStatus? @relation(fields: [salesVoucherStatusId], references: [id])\n  isDeliveryInclusive   Boolean             @default(false)\n  localPurchaseOrder    String?\n  description           String?\n  comments              String?\n  deliveryContact       String?\n  featuredImageUrl      String?\n  fileName              String?\n  quotationGeneratedAt  DateTime?\n  salesOrderGeneratedAt DateTime?\n  items                 SalesVoucherItem[]\n  salesVoucherOrders    SalesVoucherOrder[]\n  payments              Payment[]\n  createdAt             DateTime            @default(now())\n  updatedAt             DateTime            @updatedAt\n}\n\nmodel SalesVoucherItem {\n  id                   Int                 @id @default(autoincrement())\n  salesVoucherId       Int\n  salesVoucher         SalesVoucher        @relation(fields: [salesVoucherId], references: [id], onDelete: Cascade)\n  productId            Int\n  product              Product             @relation(fields: [productId], references: [id])\n  quantity             Float // Quantity per truck/sales order\n  trucksCount          Int                 @default(1) // Number of trucks/sales orders\n  unitPrice            Float?\n  totalPrice           Float?\n  discount             Float?              @default(0.0)\n  tax                  Float?              @default(0.0)\n  sourceLocationId     Int?\n  sourceLocation       Location?           @relation(\"ItemSourceLocation\", fields: [sourceLocationId], references: [id])\n  destinationId        Int?\n  destination          Destination?        @relation(fields: [destinationId], references: [id])\n  isDeliveryInclusive  Boolean             @default(false)\n  customerRef          String?\n  deliveryDate         DateTime?\n  vehicleId            Int?\n  vehicle              Vehicle?            @relation(fields: [vehicleId], references: [id])\n  driverId             Int?\n  driver               Driver?             @relation(fields: [driverId], references: [id])\n  salesVoucherStatusId Int?\n  cancellationReason   String?\n  salesVoucherOrders   SalesVoucherOrder[]\n  createdAt            DateTime            @default(now())\n  updatedAt            DateTime            @updatedAt\n}\n\nmodel SalesVoucherOrder {\n  id                        Int                      @id @default(autoincrement())\n  salesOrderNumber          String                   @unique\n  salesVoucherId            Int\n  salesVoucher              SalesVoucher             @relation(fields: [salesVoucherId], references: [id], onDelete: Cascade)\n  salesVoucherItemId        Int?\n  salesVoucherItem          SalesVoucherItem?        @relation(fields: [salesVoucherItemId], references: [id])\n  customerId                Int\n  customer                  Customer                 @relation(fields: [customerId], references: [id])\n  companyId                 Int\n  company                   Company                  @relation(fields: [companyId], references: [id])\n  locationId                Int\n  location                  Location                 @relation(fields: [locationId], references: [id])\n  productId                 Int\n  product                   Product                  @relation(fields: [productId], references: [id])\n  quantity                  Float\n  amountUnitPrice           Float?\n  amountVAT                 Float?\n  amountTotal               Float?\n  salesVoucherOrderStatusId Int                      @default(10) // 10 = Unconfirmed, 20 = Confirmed\n  salesVoucherOrderStatus   SalesVoucherOrderStatus? @relation(fields: [salesVoucherOrderStatusId], references: [id])\n  customerRef               String?\n  destinationId             Int?\n  destination               Destination?             @relation(fields: [destinationId], references: [id])\n  deliveryType              String?                  @default(\"EXW\")\n  salesOrderCreated         DateTime?                @default(now())\n  createdAt                 DateTime                 @default(now())\n  updatedAt                 DateTime                 @updatedAt\n}\n\n// ----------------------------------------------------------------------------\n// 6. Payments, Proof of Payment (PoP) & Multimodal AI Transcriptions\n// ----------------------------------------------------------------------------\n\nmodel Payment {\n  id                    Int                    @id @default(autoincrement())\n  salesVoucherId        Int?\n  salesVoucher          SalesVoucher?          @relation(fields: [salesVoucherId], references: [id])\n  customerId            Int?\n  customer              Customer?              @relation(fields: [customerId], references: [id])\n  paymentReference      String                 @unique\n  customReference       String?\n  amount                Float\n  amountApproved        Float?\n  paymentModeId         Int\n  paymentMode           PaymentMode            @relation(fields: [paymentModeId], references: [id])\n  paymentStatusId       Int                    @default(1) // 1: Pending, 2: Approved, 3: Rejected\n  paymentStatus         PaymentStatus?         @relation(fields: [paymentStatusId], references: [id])\n  transactionId         String?\n  rejectionComment      String?\n  availableBalanceRef   String?\n  ePaymentCheckOutUrl   String?\n  paymentTranscriptions PaymentTranscription[]\n  paymentDocuments      PaymentDocument[]\n  createdAt             DateTime               @default(now())\n  updatedAt             DateTime               @updatedAt\n}\n\nmodel PaymentTranscription {\n  id                           Int          @id @default(autoincrement())\n  paymentId                    Int\n  payment                      Payment      @relation(fields: [paymentId], references: [id], onDelete: Cascade)\n  documentTypeId               Int\n  documentType                 DocumentType @relation(fields: [documentTypeId], references: [id])\n  bankId                       Int?\n  bank                         Bank?        @relation(fields: [bankId], references: [id])\n  bankBranchId                 Int?\n  bankBranch                   BankBranch?  @relation(fields: [bankBranchId], references: [id])\n  amount                       Float?\n  depositorName                String?\n  depositorContact             String?\n  documentDate                 DateTime?\n  documentReference            String?\n  paymentTranscriptionStatusId Int?         @default(1)\n  notes                        String?\n  createdAt                    DateTime     @default(now())\n  updatedAt                    DateTime     @updatedAt\n}\n\nmodel PaymentDocument {\n  id           Int      @id @default(autoincrement())\n  paymentId    Int\n  payment      Payment  @relation(fields: [paymentId], references: [id], onDelete: Cascade)\n  documentName String\n  documentUrl  String\n  createdAt    DateTime @default(now())\n}\n"
}

